import json
import csv

with open('json/budget.json', 'r') as f:
    budget_data = json.load(f)

budget_lookup = {}
for record in budget_data.get('records', []):
    budget_lookup[record['budget_id']] = record

expenses = []
with open('csv/expense.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        expenses.append(row)

october_meeting_event_id = 'recggMW2eyCYceNcy'

result = []
for exp in expenses:
    budget_id = exp.get('link_to_budget', '')
    if budget_id in budget_lookup:
        budget = budget_lookup[budget_id]
        if budget.get('link_to_event') == october_meeting_event_id:
            if exp.get('approved', '').strip() == 'true':
                result.append({'expense_description': exp['expense_description'], 'cost': float(exp['cost'])})

totals = {}
for r in result:
    desc = r['expense_description']
    if desc not in totals:
        totals[desc] = 0.0
    totals[desc] += r['cost']

rows = [[desc, round(total, 2)] for desc, total in totals.items()]
for row in rows:
    print(row)
print('Total rows:', len(rows))
print('Total entries:', len(result))

